1: /**
2:  * ALE-378: the one translation from a Beginners' Workshop command's Phoenix
3:  * response to a remote-form result.
4:  *
5:  * Phoenix names the field a refusal is about (`DhcWeb.BeginnersWorkshopsHTTP`),
6:  * dotted for a workshop in a Schedule batch (`workshops.1.contactFromDate`).
7:  * `formPath` maps that public name onto the form's own field path; each
8:  * mapped field becomes an issue thrown through `invalid`, so it lands under
9:  * the right control. Anything else answers `{ ok: false, error }` with the
10:  * problem `detail`, or the command's fallback.
11:  *
12:  * Request-free: the `.remote.ts` file authorizes and makes the generated call.
13:  * The success / `invalid` plumbing is `commandResult`, shared with
14:  * `inventoryCommand`.
15:  */
16: import {
17: 	type CommandResponse,
18: 	type CommandResult,
19: 	commandResult,
20: } from "#lib/server/api/command-result.js";
21: 
22: export type BeginnersWorkshopCommandResponse<Data> = CommandResponse<Data>;
23: export type BeginnersWorkshopCommandResult<Data> = CommandResult<Data>;
24: 
25: /** A form field path: object keys and array indexes. */
26: export type FormPath = readonly (string | number)[];
27: 
28: export interface BeginnersWorkshopCommandTranslation {
29: 	/** Form-level message when Phoenix sends no `detail`. */
30: 	fallback: string;
31: 	/** The form path for a Phoenix field, or `undefined` when no control shows it. */
32: 	formPath: (field: string) => FormPath | undefined;
33: }
34: 
35: export async function beginnersWorkshopCommand<Data>(
36: 	request: Promise<BeginnersWorkshopCommandResponse<Data>>,
37: 	translation: BeginnersWorkshopCommandTranslation,
38: ): Promise<BeginnersWorkshopCommandResult<Data>> {
39: 	// A field no control shows is dropped; the mapped ones carry the refusal.
40: 	return commandResult(request, translation.fallback, (fields) => ({
41: 		issues: fields.flatMap(({ field, messages }) => {
42: 			const path = translation.formPath(field);
43: 			return path ? messages.map((message) => ({ message, path })) : [];
44: 		}),
45: 		unattributed: false,
46: 	}));
47: }
48: 
49: /** Splits a dotted Phoenix field into a form path (`workshops.1.date` → `["workshops", 1, "date"]`). */
50: export function dottedPath(field: string): FormPath {
51: 	return field
52: 		.split(".")
53: 		.map((segment) => (/^\d+$/.test(segment) ? Number(segment) : segment));
54: }

