1: /**
2:  * ALE-394: the Reschedule dialog's prefill and warning. Phoenix decides the
3:  * reschedule (`reschedule_workshop`); this module only proposes the same
4:  * kept offsets so the dialog opens — and follows a new date or time — with
5:  * the values Phoenix would keep:
6:  *
7:  * - the Payment Cutoff keeps its Dublin civil offset before the start;
8:  * - while Batch 1 hasn't gone out, the contact-from date keeps its days
9:  *   before the workshop date, or comes forward to Dublin today when that
10:  *   would fall after the cutoff date.
11:  */
12: import type {
13: 	BeginnersWorkshop,
14: 	BeginnersWorkshopConsole,
15: } from "@dhc/api-client";
16: 
17: /** A Dublin civil date (`YYYY-MM-DD`) and wall time (`HH:MM`). */
18: export interface CivilDateTime {
19: 	date: string;
20: 	time: string;
21: }
22: 
23: /** A civil date and wall time as minutes since the epoch, ignoring zones. */
24: function civilMinutes(date: string, time: string): number {
25: 	const [year, month, day] = date.split("-").map(Number);
26: 	const [hour, minute] = time.split(":").map(Number);
27: 	return Date.UTC(year, month - 1, day, hour, minute) / 60_000;
28: }
29: 
30: function civilFromMinutes(minutes: number): CivilDateTime {
31: 	const iso = new Date(minutes * 60_000).toISOString();
32: 	return { date: iso.slice(0, 10), time: iso.slice(11, 16) };
33: }
34: 
35: function addDays(date: string, days: number): string {
36: 	return civilFromMinutes(civilMinutes(date, "00:00") + days * 1440).date;
37: }
38: 
39: function daysBetween(from: string, to: string): number {
40: 	return Math.round(
41: 		(civilMinutes(to, "00:00") - civilMinutes(from, "00:00")) / 1440,
42: 	);
43: }
44: 
45: /** The cutoff date and time that keep the current offset before a new start. */
46: export function keptCutoff(
47: 	workshop: Pick<
48: 		BeginnersWorkshop,
49: 		"date" | "startTime" | "paymentCutoffDate" | "paymentCutoffTime"
50: 	>,
51: 	date: string,
52: 	startTime: string,
53: ): CivilDateTime {
54: 	const offset =
55: 		civilMinutes(workshop.date, workshop.startTime) -
56: 		civilMinutes(workshop.paymentCutoffDate, workshop.paymentCutoffTime);
57: 	return civilFromMinutes(civilMinutes(date, startTime) - offset);
58: }
59: 
60: /**
61:  * The contact-from date that keeps its days before a new date, or `today`
62:  * when that would fall after the cutoff date.
63:  */
64: export function keptContactFrom(
65: 	workshop: Pick<BeginnersWorkshop, "date" | "contactFromDate">,
66: 	date: string,
67: 	cutoffDate: string,
68: 	today: string,
69: ): string {
70: 	const kept = addDays(
71: 		date,
72: 		-daysBetween(workshop.contactFromDate, workshop.date),
73: 	);
74: 	return kept > cutoffDate ? today : kept;
75: }
